<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    owl:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">equivalentClass</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> locn:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ;</span></span>
